import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2022-01-06","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-01-06","date":"2022-01-06T00:00:00.000Z","updated":"2022-01-12T00:00:00.000Z","tags":["Ceph","分布式存储","Pull Request","性能优化","内存管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-01-06.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-01-06.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Ceph_Performance_Meeting_2022-01-06.md"};function o(n,e,s,h,d,p){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph性能会议主要讨论了多个Pull Request (PR)，包括新提交、已关闭和正在进行中的PR。会议涵盖了技术讨论和后续行动计划，重点关注性能优化和内存管理。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>新提交的PR</strong></p><ul><li>PR 4479：使用线程局部指针变量保存shard，目前处于初步评论阶段。</li><li>PR 4466：重写硬件文档，着重讨论了NVMe驱动器上的性能优化。</li></ul></li><li><p><strong>已关闭的PR</strong></p><ul><li>Igor的PR：清理onode代码中的pinning，已被合并。</li><li>优化对象内存分配的PR：因反馈关闭。</li></ul></li><li><p><strong>正在进行中的PR</strong></p><ul><li>管理器TTL缓存实现更新。</li><li>Josh的平衡器工作，正在进行中，计划通过tautology进行测试。</li><li>Igor的PR：减少shared blob FSDK的RAM使用，进行中。</li></ul></li><li><p><strong>其他讨论</strong></p><ul><li>omap benchmark的讨论，考虑重写以适应现有OSD环境。</li><li>Casey汇报了rgw性能相关的PR进展，特别是beast前端的变化。</li><li>Gabby汇报了分配器更改的修复工作进展。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>鼓励团队成员审查新提交的PR。</li><li>硬件文档更新建议更细致地说明核心需求。</li><li>进一步讨论omap benchmark。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续审查和更新PR，确保代码质量和性能优化。</li><li>安排下一次会议，讨论omap benchmark和可能的技术改进。</li><li>关注并评估新提交的PR，特别是那些可能影响性能和稳定性的PR。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>部分技术讨论需要Adam和Igor的参与，相关议题将推迟到他们参与的下次会议。</li><li>讨论了性能优化和内存管理的潜在改进，将在后续的开发和测试中进一步探索。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题后结束，感谢所有参与者的贡献，并期待下周的会议。</p>',13)])])}const P=a(r,[["render",o]]);export{c as __pageData,P as default};
